export function prepareStripePayment(store:LedgerStore,paymentId:string,mode:'test'|'live',tenantId='owner',accountId:string|null=null){const current=store.one<{provider:string;provider_mode:string|null;provider_account_id:string|null;status:string}>('SELECT provider,provider_mode,provider_account_id,status FROM payments WHERE id=? AND tenant_id=?',paymentId,tenantId);if(!current||current.status!=='pending')throw new ApiError(409,'payment_not_pending','This payment is no longer pending.');if(current.provider==='stripe'&&current.provider_mode&&current.provider_mode!==mode)throw new ApiError(409,'provider_mode_conflict','This payment was started in a different Stripe mode.');store.run("UPDATE payments SET provider='stripe',provider_mode=?,provider_account_id=? WHERE id=? AND tenant_id=? AND status='pending'",mode,accountId,paymentId,tenantId);}
