export function stripeRefundContext(store:LedgerStore,refundId:string){const row=store.one<{id:string;payment_id:string;tenant_id:string;amount:number;status:string;provider_mode:string;payment_intent:string|null;provider_account_id:string|null}>('SELECT refunds.id,refunds.payment_id,refunds.tenant_id,refunds.amount,refunds.status,refunds.provider_mode,payments.provider_payment_intent AS payment_intent,payments.provider_account_id FROM refunds JOIN payments ON payments.id=refunds.payment_id AND payments.tenant_id=refunds.tenant_id WHERE refunds.id=?',refundId);if(!row||row.status!=='pending'||!row.payment_intent)throw new ApiError(409,'refund_not_ready','Stripe refund is not ready to submit; payment confirmation may still be pending.');return row;}
