 let verified:{event:StripeEvent;mode:'test'|'live'}|undefined;
 for(const [mode,secret] of candidates){if(!secret)continue;try{verified={event:verifyStripeWebhook(rawBody,signature,secret),mode};break;}catch(error){if(!(error instanceof ApiError)||error.code!=='invalid_webhook_signature')throw error;}}
